 int y0=max(0,(int)floor(s.y-abs(hy)-s.r-1)),y1=min(N-1,(int)ceil(s.y+abs(hy)+s.r+1));
 double gains[16]={0};
 for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++){
  float xx=x-s.x,yy=y-s.y;float u=xx*dx+yy*dy,v=-xx*dy+yy*dx;
  float q=max(0.f,abs(u)-s.len/2);float d=sqrt(q*q+v*v);
  float a=clamp((s.r+.7f-d)/1.4f,0.f,1.f);if(a==0)continue;
